    {"foundation": "authority", "basis": "Crime/Law and order/Violence/Vandalism, Local government/Council tax/Poll tax, Public services in general, Taxation, Race relations/Immigration/Immigrants and Defence (order/security aspects)", "weight": 0.20},
    {"foundation": "equality", "basis": "Poverty/Inequality, Low pay/Minimum wage/Fair wages, Housing, Education/Schools (equal opportunity), NHS/Hospitals/Healthcare (equal access), Pensions/Social security", "weight": 0.18},
